"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Step 0 (P1 v0.3, section 8 item 6): FSD50K counts per event and decoy class.

Reads only the FSD50K ground truth and metadata (no audio). For each class reports clips under CC0 or CC BY,
"clean" clips (the class is the clip's only leaf label, so no other labelled source), clips whose leaf rating is
present-and-predominant (PP, no PNP/NP rating), and the number of distinct uploaders.

usage: python scripts/step0_fsd50k_counts.py <FSD50K extract dir> <output json>
"""
import csv
import json
import os
import re
import sys
from collections import Counter, defaultdict

EVENTS = ["Doorbell", "Knock", "Telephone", "Ringtone"]
DECOY_CANDIDATES = [
    "Dishes_and_pots_and_pans", "Cutlery_and_silverware", "Water_tap_and_faucet", "Sink_(filling_or_washing)",
    "Typing", "Computer_keyboard", "Typewriter", "Frying_(food)", "Boiling", "Crumpling_and_crinkling",
    "Chirp_and_tweet", "Bird_vocalization_and_bird_call_and_bird_song", "Printer", "Scissors", "Zipper_(clothing)",
    "Tearing", "Writing", "Packing_tape_and_duct_tape", "Toilet_flush", "Coin_(dropping)", "Drawer_open_or_close",
    "Cupboard_open_or_close", "Microwave_oven", "Tick-tock", "Raindrop",
]
EXCLUDED_FOR_REFERENCE = ["Bark", "Dog", "Car", "Walk_and_footsteps", "Door", "Sliding_door", "Hammer", "Bell", "Chime",
                          "Buzz", "Alarm", "Cough", "Shatter", "Music", "Speech"]
OK_LICENSE = re.compile(r"creativecommons\.org/(publicdomain/zero/1\.0|licenses/by/[34]\.0)/?$")


def load(root):
    gt = {}
    for split in ("dev", "eval"):
        with open(os.path.join(root, "FSD50K.ground_truth", f"{split}.csv"), encoding="utf-8") as f:
            for row in csv.DictReader(f):
                gt[row["fname"]] = {"labels": row["labels"].split(","), "mids": row["mids"].split(","),
                                    "split": split}
    info = {}
    for split in ("dev", "eval"):
        info.update(json.load(open(os.path.join(root, "FSD50K.metadata", f"{split}_clips_info_FSD50K.json"),
                                   encoding="utf-8")))
    ratings = json.load(open(os.path.join(root, "FSD50K.metadata", "pp_pnp_ratings_FSD50K.json"), encoding="utf-8"))
    return gt, info, ratings


def infer_ancestors(gt):
    """B is an ancestor of A when every clip labelled A is also labelled B and B is more frequent (labels are
    propagated up the AudioSet hierarchy in FSD50K)."""
    count = Counter(l for c in gt.values() for l in c["labels"])
    co = defaultdict(Counter)
    for c in gt.values():
        for a in c["labels"]:
            for b in c["labels"]:
                if a != b:
                    co[a][b] += 1
    return {a: {b for b, n in co[a].items() if n == count[a] and count[b] > count[a]} for a in count}


def main(root, out_path):
    gt, info, ratings = load(root)
    anc = infer_ancestors(gt)
    name2mid = {l: m for c in gt.values() for l, m in zip(c["labels"], c["mids"])}
    rows = {}
    for cls in EVENTS + DECOY_CANDIDATES + EXCLUDED_FOR_REFERENCE:
        if cls not in name2mid:
            rows[cls] = {"missing": True}
            continue
        mid = name2mid[cls]
        allc = [f for f, c in gt.items() if cls in c["labels"]]
        lic = [f for f in allc if OK_LICENSE.search(info[f]["license"])]
        clean = []
        for f in lic:
            labs = set(gt[f]["labels"])
            leaves = {l for l in labs if not any(l in anc.get(o, ()) for o in labs if o != l)}
            if leaves == {cls}:
                clean.append(f)
        pp = [f for f in clean if (r := ratings.get(f, {}).get(mid)) and 1.0 in r and min(r) >= 1.0]
        up = Counter(info[f]["uploader"] for f in pp)
        rows[cls] = {
            "all": len(allc), "cc0_ccby": len(lic), "clean": len(clean), "clean_pp": len(pp),
            "clean_pp_dev": sum(gt[f]["split"] == "dev" for f in pp),
            "clean_pp_eval": sum(gt[f]["split"] == "eval" for f in pp),
            "uploaders_clean_pp": len(up), "top_uploader_share": round(max(up.values()) / len(pp), 3) if pp else None,
            "clips_clean_pp": sorted(pp, key=int),
        }
    if "Telephone" in rows and not rows["Telephone"].get("missing"):
        tel = rows["Telephone"]["clips_clean_pp"]
        text = {f: (info[f]["title"] + " " + " ".join(info[f]["tags"] if isinstance(info[f]["tags"], list)
                                                       else [str(info[f]["tags"])])).lower() for f in tel}
        ring = [f for f in tel if "ring" in text[f] and not re.search(r"dial|dtmf|busy|touch.?tone", text[f])]
        rows["Telephone"]["ring_keyword_clips"] = len(ring)
        rows["Telephone"]["ring_keyword_uploaders"] = len({info[f]["uploader"] for f in ring})
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    json.dump(rows, open(out_path, "w", encoding="utf-8"), indent=1)
    print(f"{'class':45s} {'all':>5s} {'cc0/by':>6s} {'clean':>5s} {'PP':>5s} {'dev':>4s} {'eval':>4s} {'upl':>4s} {'top':>5s}")
    for cls, r in rows.items():
        if r.get("missing"):
            print(f"{cls:45s} MISSING")
            continue
        print(f"{cls:45s} {r['all']:5d} {r['cc0_ccby']:6d} {r['clean']:5d} {r['clean_pp']:5d} {r['clean_pp_dev']:4d} "
              f"{r['clean_pp_eval']:4d} {r['uploaders_clean_pp']:4d} {str(r['top_uploader_share']):>5s}"
              + (f"  ring-keyword {r['ring_keyword_clips']} clips / {r['ring_keyword_uploaders']} uploaders"
                 if "ring_keyword_clips" in r else ""))


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
